const getRetryDelay = (
  error: unknown,
  attempt: number,
  baseDelayMs: number,
  jitter: boolean,
  retryAfterMs: RetryWithBackoffOptions['retryAfterMs'],
) => {
  const backoffMs = baseDelayMs * 2 ** attempt;
  return Math.max(
    jitter ? Math.random() * backoffMs : backoffMs,
    retryAfterMs?.(error) ?? 0,
  );
};

